using System.Collections;
using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "MercifulConvergenceAction", menuName = "Data/Battle/Battle Actions/Orion/MercifulConvergence Action")]
public class MercifulConvergenceAction : StarRequirementEffectAction
{
	[Header("Star Requirement")]
	[SerializeField]
	private StarAbility starAbility;

	[SerializeField]
	private int karmicOrbActivationAmount = 1;

	public StarAbility StarAbility => starAbility;

	public int KarmicOrbActivationAmount => karmicOrbActivationAmount;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(ApplyEffectAndActivateStarAbility(target, amount, source));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
	}

	private IEnumerator ApplyEffectAndActivateStarAbility(GameObject target, int amount, GameObject source)
	{
		DefaultCast(target, amount, source, effectFeedback: true, gainingEffectVFXAndSFX: true);
		yield return InvokeAlternatives.WaitForFrames(3);
		OrionAstrarium orionAstrarium = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().OrionAstrarium;
		if (orionAstrarium != null)
		{
			yield return ReferenceSingleton<CoroutineHandler>.Instance.Run(orionAstrarium.ActivateStarAbility(karmicOrbActivationAmount, starAbility));
		}
	}
}
